def transform(grid):
    g = np.array(grid)
    order = []
    for v in g.flatten():
        if int(v) not in order:
            order.append(int(v))
    counts = {c: int((g == c).sum()) for c in order}
    cols = sorted(order, key=lambda c: (-counts[c], order.index(c)))
    h = counts[cols[0]]
    out = np.zeros((h, len(cols)), dtype=int)
    emit(out, f"Allocate a {h}x{len(cols)} canvas of 0: height = largest colour count ({h}), one column per colour.")
    for x, c in enumerate(cols):
        out[:counts[c], x] = c
        emit(out, f"Column {x}: colour {c} appears {counts[c]} times, so draw a bar of length {counts[c]} from the top.")
    return out
